<h2>Create a robots.txt starting point</h2><p class="lead">Build user-agent, allow, disallow and sitemap directives with explicit line-by-line output.</p><div class="form-grid"><div class="field"><label for="ua">User-agent</label><input id="ua" value="*"></div><div class="field"><label for="sm">Sitemap URL</label><input id="sm" type="url" placeholder="https://example.com/sitemap.xml"></div><div class="field"><label for="allow">Allow paths — one per line</label><textarea id="allow" placeholder="/public/"></textarea></div><div class="field"><label for="disallow">Disallow paths — one per line</label><textarea id="disallow" placeholder="/private/&#10;/tmp/"></textarea></div></div><div class="tool-actions"><button class="btn btn-primary" id="gen">Generate</button><button class="btn btn-secondary" id="copy">Copy</button></div><div class="result-box"><pre class="code-output" id="out"></pre></div><div class="notice"><strong>Remember:</strong> robots.txt manages crawler access; it is not an authentication or privacy mechanism.</div>
<script>(()=>{const $=i=>document.getElementById(i);function lines(v){return v.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}function go(){let a=['User-agent: '+($('ua').value.trim()||'*')];lines($('allow').value).forEach(x=>a.push('Allow: '+x));lines($('disallow').value).forEach(x=>a.push('Disallow: '+x));if($('sm').value.trim())a.push('','Sitemap: '+$('sm').value.trim());$('out').textContent=a.join('\n')}document.querySelectorAll('#ua,#sm,#allow,#disallow').forEach(x=>x.addEventListener('input',go));$('gen').onclick=go;$('copy').onclick=()=>tkCopy($('out').textContent);go()})();</script>
